-- Track M D-M1 (Day 1): the TOPIC target type, and a run's record that it rests
-- on person data by its target alone. Generated by drizzle-kit from
-- src/schema/enums.ts and src/schema/work.ts. Expand only:
--   - TOPIC is appended to target_type (forward-only; nothing here uses it as
--     an enum value, which the transaction that adds it could not do);
--   - runs.person_bearing defaults to false for the rows already there. A run
--     planned before this ran had no TOPIC to plan. A run still queued when it
--     runs is planned by the new code: should that plan a TOPIC job, 0026
--     refuses the job (PTT01), nothing is collected, and the run is FAILED with
--     that code (RunCoordinator). The runs repository sets person_bearing on
--     every new run from the investigation's target (runRestsOnPersonTarget,
--     @repo/access);
--   - the check refuses a run that chose a person target type without it,
--     comparing as text for the same reason (PERSON_TARGET_TYPES). Every
--     existing row passes it: none can hold the new value;
--   - the jobs index is how the person-data probe's run check reads a run's
--     jobs. Plain CREATE INDEX, as 0024.
-- 0026 keeps the record true for jobs and states the grants.
ALTER TYPE "public"."target_type" ADD VALUE 'TOPIC';--> statement-breakpoint
ALTER TABLE "runs" ADD COLUMN "person_bearing" boolean DEFAULT false NOT NULL;--> statement-breakpoint
CREATE INDEX "jobs_run_idx" ON "jobs" USING btree ("tenant_id","run_id");--> statement-breakpoint
ALTER TABLE "runs" ADD CONSTRAINT "runs_person_target_recorded" CHECK ("runs"."person_bearing" or "runs"."requested_target_type" is null or "runs"."requested_target_type"::text not in ('TOPIC'));